// Find DD tasks and validate prerequisites
const tasks = $input.first().json.result || [];
console.log(`🔍 Scanning ${tasks.length} Kanboard tasks`);

// Find DD tasks
let ddTask = null;
for (const task of tasks) {
  const title = task.title ? task.title.toString() : '';
  if (title.toLowerCase().includes('due diligence:')) {
    ddTask = task;
    break;
  }
}

if (!ddTask) {
  console.log('ℹ️ No Due Diligence tasks found');
  throw new Error('No Due Diligence tasks found');
}

console.log(`🎯 Processing DD Task: ${ddTask.title}`);

// Validate prerequisites
const errors = [];
const title = ddTask.title || '';
const description = ddTask.description || '';

// Extract company name
const companyMatch = title.match(/due diligence:\s*(.+)/i);
const companyName = companyMatch ? companyMatch[1].trim() : '';
if (!companyName) {
  errors.push('Title must be "Due Diligence: [Company Name]"');
}

// Extract website URL
const urlMatch = description.match(/https?:\/\/[^\s]+/);
const websiteUrl = urlMatch ? urlMatch[0] : '';
if (!websiteUrl) {
  errors.push('Description must contain official website URL');
}

return {
  json: {
    task_id: ddTask.id,
    project_id: ddTask.project_id || 1,
    title: title,
    description: description,
    company_name: companyName,
    website_url: websiteUrl,
    errors: errors,
    has_errors: errors.length > 0
  }
};

// Check for PDFs and generate KB hash
const taskData = $('Find & Validate DD Task').first().json;
const attachResponse = $input.first().json;
const attachments = attachResponse.result || [];

console.log(`📎 Found ${attachments.length} attachments`);

// Filter PDF attachments
const pdfAttachments = attachments.filter(att => 
  att.name && att.name.toLowerCase().endsWith('.pdf')
);

if (pdfAttachments.length === 0) {
  return {
    json: {
      ...taskData,
      errors: [...taskData.errors, 'No PDF attachments found'],
      has_errors: true
    }
  };
}

console.log(`📄 Found ${pdfAttachments.length} PDF files`);

// Generate content hash for KB cache
let contentHash = '';
contentHash += taskData.website_url;
for (const pdf of pdfAttachments) {
  contentHash += `${pdf.name}:${pdf.size || 0}`;
}

// Simple hash function
function simpleHash(str) {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    const char = str.charCodeAt(i);
    hash = ((hash << 5) - hash) + char;
    hash = hash & hash; // Convert to 32-bit integer
  }
  return Math.abs(hash).toString(16);
}

const kbHash = simpleHash(contentHash);

return {
  json: {
    ...taskData,
    attachments: attachments,
    pdf_attachments: pdfAttachments,
    kb_hash: kbHash,
    total_pdfs: pdfAttachments.length
  }
};

// Process PDFs using PDF.co API
const taskData = $('Check PDFs & Generate Hash').first().json;
const pdfAttachments = taskData.pdf_attachments || [];

console.log(`🔄 Processing ${pdfAttachments.length} PDFs`);

const pdfTexts = [];

// For now, simulate PDF text extraction
// In real implementation, you'd call PDF.co API for each PDF
for (let i = 0; i < pdfAttachments.length; i++) {
  const pdf = pdfAttachments[i];

  // TODO: Replace with actual PDF.co API call
  // const extractResponse = await fetch('https://api.pdf.co/v1/pdf/convert/to/text', {
  //   method: 'POST',
  //   headers: { 'Content-Type': 'application/json', 'x-api-key': 'YOUR_API_KEY' },
  //   body: JSON.stringify({ url: pdf.download_url })
  // });

  // Placeholder extracted text
  const extractedText = `PDF Content from ${pdf.name}:\n\nThis document contains financial information, business model details, and operational metrics for ${taskData.company_name}. Revenue streams include subscriptions and professional services. Key metrics show growth trajectory with monthly recurring revenue increasing quarter over quarter.`;

  pdfTexts.push({
    filename: pdf.name,
    content: extractedText,
    source_type: 'pdf',
    pages: 1 // Placeholder
  });
}

console.log(`✅ Extracted text from ${pdfTexts.length} PDFs`);

return {
  json: {
    ...taskData,
    pdf_texts: pdfTexts
  }
};

// Build comprehensive Knowledge Base
const taskData = $('Extract PDF Text').first().json;
let websiteContent = '';
let finbertData = null;

// Get website content
try {
  const websiteResponse = $('Fetch Website').first();
  if (websiteResponse && websiteResponse.data) {
    websiteContent = websiteResponse.data.toString().substring(0, 10000); // Limit size
  }
} catch (error) {
  console.log('Website fetch failed:', error.message);
}

// Get FinBERT results
try {
  const finbertResponse = $('Run FinBERT Analysis').first();
  if (finbertResponse && finbertResponse.json) {
    finbertData = finbertResponse.json;
  }
} catch (error) {
  console.log('FinBERT failed:', error.message);
}

// Create KB chunks
let kbChunks = [];
let chunkCounter = 1;

// Add task metadata
kbChunks.push({
  chunk_id: `kb://${taskData.task_id}/task:title/p1#c${chunkCounter++}`,
  content: `Company: ${taskData.company_name}. Task: ${taskData.title}`,
  source_type: 'task',
  source_id: 'task_metadata',
  location: 'title'
});

kbChunks.push({
  chunk_id: `kb://${taskData.task_id}/task:description/p1#c${chunkCounter++}`,
  content: `Description: ${taskData.description}`,
  source_type: 'task',
  source_id: 'task_metadata',
  location: 'description'
});

// Chunk website content
if (websiteContent) {
  const websiteChunks = chunkText(websiteContent, 800);
  const hostname = new URL(taskData.website_url).hostname;

  websiteChunks.forEach((chunk, index) => {
    kbChunks.push({
      chunk_id: `kb://${taskData.task_id}/website:${hostname}/p${index + 1}#c${chunkCounter++}`,
      content: chunk,
      source_type: 'website',
      source_id: taskData.website_url,
      location: `page_${index + 1}`
    });
  });
}

// Chunk PDF content
if (taskData.pdf_texts) {
  taskData.pdf_texts.forEach(pdf => {
    const pdfChunks = chunkText(pdf.content, 800);
    pdfChunks.forEach((chunk, index) => {
      kbChunks.push({
        chunk_id: `kb://${taskData.task_id}/pdf:${pdf.filename}/p${index + 1}#c${chunkCounter++}`,
        content: chunk,
        source_type: 'pdf',
        source_id: pdf.filename,
        location: `page_${index + 1}`
      });
    });
  });
}

// Add FinBERT analysis
if (finbertData) {
  kbChunks.push({
    chunk_id: `kb://${taskData.task_id}/finance:finbert/p1#c${chunkCounter++}`,
    content: `FinBERT Financial Analysis: ${JSON.stringify(finbertData)}`,
    source_type: 'finance',
    source_id: 'finbert_analysis',
    location: 'analysis_result'
  });
}

function chunkText(text, chunkSize) {
  const words = text.split(/\s+/);
  const chunks = [];
  let currentChunk = [];

  for (const word of words) {
    currentChunk.push(word);
    if (currentChunk.length >= chunkSize * 0.75) {
      chunks.push(currentChunk.join(' '));
      currentChunk = [];
    }
  }

  if (currentChunk.length > 0) {
    chunks.push(currentChunk.join(' '));
  }

  return chunks;
}

console.log(`📚 Built KB with ${kbChunks.length} chunks`);

// Store KB in workflow data for persistence
// In real implementation, you'd store this in a database
const kbStore = {
  task_id: taskData.task_id,
  kb_hash: taskData.kb_hash,
  chunks: kbChunks,
  created_at: new Date().toISOString(),
  total_chunks: kbChunks.length
};

return {
  json: {
    ...taskData,
    kb_chunks: kbChunks,
    kb_store: kbStore,
    total_kb_chunks: kbChunks.length
  }
};

// Initialize OUT_STORE and find next section to process
const taskData = $input.first().json;

// 20 canonical sections
const sections = [
  'Introduction & Engagement Context',
  'Methodology & Reliability Levels', 
  'Company Overview',
  'Business Model & Unit Economics',
  'Products & Technology',
  'Target Market & Competitive Set',
  'Financials (Multi-Year, reconciled & recomputed)',
  'Cash, Burn, Runway',
  'Revenue Quality & Client Cohorts',
  'Partnerships & Ecosystem',
  'Intellectual Property',
  'Legal & Regulatory',
  'Governance & Board Effectiveness',
  'Capital Structure & Dilution',
  'Risk Matrix & Mitigations',
  'Gaps, Uncertainties & Disclaimers',
  'Scenario Analysis',
  'Strategic Options',
  'Recommendations & Next Steps',
  'Source Map & Integrity Log'
];

// Initialize OUT_STORE (in real implementation, this would be in database)
const outStore = {
  task_id: taskData.task_id,
  sections: sections.map(name => ({
    name: name,
    status: 'draft', // draft|checked|approved
    maker_version: 0,
    maker_md: '',
    checker_json: null,
    approver_json: null,
    issues: [],
    last_updated: new Date().toISOString()
  })),
  created_at: new Date().toISOString()
};

// Find first section that needs work
const nextSection = outStore.sections.find(section => 
  section.status !== 'approved'
);

if (!nextSection) {
  // All sections approved - go to final assembly
  console.log('🎉 All sections approved - ready for final assembly');
  return {
    json: {
      ...taskData,
      workflow_action: 'FINAL_ASSEMBLY',
      out_store: outStore
    }
  };
}

console.log(`📝 Next section to process: ${nextSection.name}`);

return {
  json: {
    ...taskData,
    current_section: nextSection.name,
    section_index: outStore.sections.indexOf(nextSection),
    out_store: outStore,
    workflow_action: 'PROCESS_SECTION'
  }
};

// Generate section-specific Maker prompt
const taskData = $input.first().json;
const sectionName = taskData.current_section;
const kbChunks = taskData.kb_chunks || [];

// Get relevant KB chunks for this section (simple filtering)
const relevantChunks = kbChunks.slice(0, 10); // Take first 10 chunks for now

const kbText = relevantChunks.map(chunk => 
  `[${chunk.chunk_id}]: ${chunk.content.substring(0, 300)}...`
).join('\n\n');

// Section-specific prompts
const sectionPrompts = {
  'Introduction & Engagement Context': `Focus:
- Purpose and scope of this due diligence
- Engagement context and period covered
- Information sources from KB
- Limitations based on available data`,

  'Company Overview': `Focus:
- Founding, history, mission from KB
- Leadership and ownership structure
- Operating footprint and headcount
- Key facts with KB citations`,

  'Business Model & Unit Economics': `Focus:
- Value creation and revenue generation
- Revenue streams and pricing strategy
- Key cost drivers and unit economics
- CAC, LTV, margins if available in KB`,

  'Products & Technology': `Focus:
- Product lines and technology stack
- Architecture highlights from KB
- Roadmap if mentioned
- IP components tied to products`
};

const sectionGuidance = sectionPrompts[sectionName] || `Focus:
- Analyze ${sectionName} based on KB content
- Cite all claims with [KB:chunk_id]
- State missing information explicitly`;

const makerPrompt = `SYSTEM:
You are the MAKER agent for a Due Diligence report. Write exactly one section per run.
Create content ONLY from the provided Knowledge Base (KB) chunks.
DO NOT fabricate, simulate, or guess numbers. Cite KB inline as [KB:<chunk_id>] next to claims.
If information is missing in KB, explicitly state "Insufficient evidence in KB" and list what is missing.

USER:
Company: ${taskData.company_name}
Website: ${taskData.website_url}
Current Section: ${sectionName}

Relevant KB Chunks:
${kbText}

${sectionGuidance}

Write the "${sectionName}" section in professional Markdown, suitable for investors and executives.
Keep it concise, factual, and decision-oriented.
Include headings/subheadings and bullets where helpful.
Cite every claim with [KB:chunk_id] references.`;

console.log(`📝 Generated Maker prompt for: ${sectionName}`);

return {
  json: {
    ...taskData,
    maker_prompt: makerPrompt,
    relevant_chunks: relevantChunks
  }
};

// Update OUT_STORE with Maker output and prepare Checker
const taskData = $('Generate Maker Prompt').first().json;
const makerResponse = $input.first().json.response;
const sectionName = taskData.current_section;

console.log(`📄 Maker completed section: ${sectionName} (${makerResponse.length} chars)`);

// Update OUT_STORE
const outStore = { ...taskData.out_store };
const sectionIndex = taskData.section_index;

outStore.sections[sectionIndex] = {
  ...outStore.sections[sectionIndex],
  maker_md: makerResponse,
  maker_version: outStore.sections[sectionIndex].maker_version + 1,
  status: 'pending_check',
  last_updated: new Date().toISOString()
};

// Prepare Checker prompt
const checkerPrompt = `SYSTEM:
You are the CHECKER. You DO NOT write or rewrite the section.
You ONLY validate the Maker's markdown against the provided KB.
Reject anything unsupported, hallucinated, simulated, or numerically fabricated.

USER:
Section: ${sectionName}
Maker_Markdown:
${makerResponse}

Cited KB Chunks:
${taskData.relevant_chunks.map(chunk => `[${chunk.chunk_id}]: ${chunk.content.substring(0, 200)}...`).join('\n\n')}

Validation Rules:
1) All claims must be supported by cited KB chunks
2) No hallucinations
3) No mock/simulated/placeholder data or invented numbers
4) Section scope completeness
5) Internal consistency

Respond ONLY in JSON (no extra text):
{
  "approved": true|false,
  "quality_score": <integer 1-10>,
  "issues": ["specific, referenceable issues"],
  "instructions_for_maker": "actionable, concise steps to fix"
}`;

return {
  json: {
    ...taskData,
    maker_output: makerResponse,
    checker_prompt: checkerPrompt,
    out_store: outStore
  }
};

// Parse Checker JSON and decide next action
const taskData = $('Update OUT_STORE & Prepare Checker').first().json;
const checkerResponse = $input.first().json.response;
const sectionName = taskData.current_section;

let checkerData;
try {
  const jsonMatch = checkerResponse.match(/\{[\s\S]*?\}/);
  if (jsonMatch) {
    checkerData = JSON.parse(jsonMatch[0]);
  } else {
    throw new Error('No JSON found');
  }
} catch (e) {
  checkerData = {
    approved: false,
    quality_score: 1,
    issues: ['Checker response invalid: ' + e.message],
    instructions_for_maker: 'Checker failed to return valid JSON'
  };
}

console.log(`🔍 Checker result: ${checkerData.approved ? 'APPROVED' : 'REJECTED'} (Score: ${checkerData.quality_score}/10)`);

// Update OUT_STORE with Checker results
const outStore = { ...taskData.out_store };
const sectionIndex = taskData.section_index;

outStore.sections[sectionIndex] = {
  ...outStore.sections[sectionIndex],
  checker_json: checkerData,
  issues: checkerData.issues || [],
  last_updated: new Date().toISOString()
};

if (!checkerData.approved) {
  // Checker rejected - update status and prepare comment
  outStore.sections[sectionIndex].status = 'rejected';

  return {
    json: {
      ...taskData,
      checker_data: checkerData,
      out_store: outStore,
      workflow_action: 'POST_CHECKER_REJECT'
    }
  };
}

// Checker approved - prepare Approver
const approvedSections = outStore.sections
  .filter(s => s.status === 'approved')
  .map(s => s.name);

const approverPrompt = `SYSTEM:
You are the APPROVER. You DO NOT write or rewrite the section.
You make a business decision based on the Maker's text and the Checker's findings.

USER:
Section: ${sectionName}
Maker_Markdown:
${taskData.maker_output}
Checker_Findings_JSON:
${JSON.stringify(checkerData)}
Previously Approved Sections:
${approvedSections.join(', ')}

Decision Criteria:
- Business/strategic relevance for executives
- Clarity, focus, and usefulness
- No unresolved red flags from Checker

Respond ONLY in JSON (no extra text):
{
  "approved": true|false,
  "final_feedback": "business rationale (brief)",
  "send_back_instructions": "specific improvements required if rejected"
}`;

return {
  json: {
    ...taskData,
    checker_data: checkerData,
    approver_prompt: approverPrompt,
    out_store: outStore,
    workflow_action: 'RUN_APPROVER'
  }
};

// Parse Approver result and finalize section
const taskData = $('Process Checker Result').first().json;
const approverResponse = $input.first().json.response;
const sectionName = taskData.current_section;

let approverData;
try {
  const jsonMatch = approverResponse.match(/\{[\s\S]*?\}/);
  if (jsonMatch) {
    approverData = JSON.parse(jsonMatch[0]);
  } else {
    throw new Error('No JSON found');
  }
} catch (e) {
  approverData = {
    approved: false,
    final_feedback: 'Approver response invalid: ' + e.message,
    send_back_instructions: 'Approver failed to return valid JSON'
  };
}

console.log(`✅ Approver result: ${approverData.approved ? 'APPROVED' : 'REJECTED'}`);

// Update OUT_STORE with final decision
const outStore = { ...taskData.out_store };
const sectionIndex = taskData.section_index;

outStore.sections[sectionIndex] = {
  ...outStore.sections[sectionIndex],
  approver_json: approverData,
  status: approverData.approved ? 'approved' : 'rejected',
  last_updated: new Date().toISOString()
};

if (!approverData.approved) {
  return {
    json: {
      ...taskData,
      approver_data: approverData,
      out_store: outStore,
      workflow_action: 'POST_APPROVER_REJECT'
    }
  };
}

// Both Checker and Approver approved!
const approvedCount = outStore.sections.filter(s => s.status === 'approved').length;

return {
  json: {
    ...taskData,
    approver_data: approverData,
    out_store: outStore,
    approved_count: approvedCount,
    total_sections: outStore.sections.length,
    workflow_action: 'POST_SECTION_APPROVED'
  }
};

// Compile final report from all approved sections
const taskData = $('Initialize Sections & Find Next').first().json;
const outStore = taskData.out_store;

console.log('🔨 Compiling final Due Diligence report');

// Get all approved sections in order
const approvedSections = outStore.sections.filter(s => s.status === 'approved');

if (approvedSections.length < outStore.sections.length) {
  throw new Error('Not all sections are approved yet');
}

// Build complete report
let finalReport = `# Due Diligence Report: ${taskData.company_name}\n\n`;
finalReport += `**Generated:** ${new Date().toISOString()}\n`;
finalReport += `**Website:** ${taskData.website_url}\n`;
finalReport += `**Knowledge Base:** ${taskData.total_kb_chunks} chunks\n\n`;
finalReport += `---\n\n`;

// Add table of contents
finalReport += `## Table of Contents\n\n`;
outStore.sections.forEach((section, index) => {
  finalReport += `${index + 1}. ${section.name}\n`;
});
finalReport += `\n---\n\n`;

// Add all sections
outStore.sections.forEach((section, index) => {
  finalReport += `## ${index + 1}. ${section.name}\n\n`;
  finalReport += `${section.maker_md}\n\n`;
  finalReport += `---\n\n`;
});

// Add source map
finalReport += `## Source Map & Integrity Log\n\n`;
finalReport += `| Chunk ID | Source Type | Source ID | Location |\n`;
finalReport += `|---|---|---|---|\n`;

if (taskData.kb_chunks) {
  taskData.kb_chunks.forEach(chunk => {
    finalReport += `| ${chunk.chunk_id} | ${chunk.source_type} | ${chunk.source_id} | ${chunk.location} |\n`;
  });
}

finalReport += `\n**Report Generation Completed:** ${new Date().toISOString()}\n`;

console.log(`📄 Final report generated: ${finalReport.length} characters`);

return {
  json: {
    ...taskData,
    final_report: finalReport,
    report_length: finalReport.length
  }
};

// Generate PDF using simple HTML conversion
const taskData = $input.first().json;
const markdownContent = taskData.final_report;

// Convert Markdown to HTML (basic conversion)
let htmlContent = markdownContent
  .replace(/^# (.+)$/gm, '<h1>$1</h1>')
  .replace(/^## (.+)$/gm, '<h2>$1</h2>')
  .replace(/^### (.+)$/gm, '<h3>$1</h3>')
  .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
  .replace(/\*(.+?)\*/g, '<em>$1</em>')
  .replace(/\n\n/g, '</p><p>')
  .replace(/\n/g, '<br>')
  .replace(/---/g, '<hr>');

// Wrap in basic HTML
const fullHtml = `
<!DOCTYPE html>
<html>
<head>
  <title>Due Diligence Report - ${taskData.company_name}</title>
  <style>
    body { font-family: Arial, sans-serif; margin: 40px; line-height: 1.6; }
    h1 { color: #2c3e50; border-bottom: 2px solid #3498db; }
    h2 { color: #34495e; margin-top: 30px; }
    h3 { color: #7f8c8d; }
    table { border-collapse: collapse; width: 100%; margin: 20px 0; }
    th, td { border: 1px solid #ddd; padding: 8px; text-align: left; }
    th { background-color: #f2f2f2; }
    hr { margin: 30px 0; }
  </style>
</head>
<body>
  <p>${htmlContent}</p>
</body>
</html>`;

// In real implementation, you'd use PDF.co API here
// For now, we'll simulate PDF generation
const pdfFileName = `DD_Report_${taskData.company_name.replace(/\s+/g, '_')}_${new Date().toISOString().split('T')[0]}.pdf`;

console.log(`📄 Generated PDF: ${pdfFileName}`);

return {
  json: {
    ...taskData,
    pdf_html: fullHtml,
    pdf_filename: pdfFileName,
    pdf_size: fullHtml.length // Simulated size
  }
};

